with parsed as (select id, host, latency_ms, status_code, payload_json, context, context['region'] as region, get_json_object(payload_json, '$.user.id') as user_id, context['trace'] as trace from app_logs where status_code between 276 and 423) select case when latency_ms >= 2445 then 'PREMIUM' else 'STANDARD' end as latency_ms_tier, count(*) filter (where host = 'h2') as h2_rows, corr(latency_ms, status_code) as corr_latency_ms_status_code, stddev_samp(status_code) as status_code_stddev, corr(status_code, latency_ms) as corr_status_code_latency_ms from parsed group by latency_ms_tier;
